extends Node

@export var seed_val: int = 12345
@export var width: int = 64
@export var height: int = 64
@export var wall_threshold: float = 0.0

const TILE_FLOOR = 0
const TILE_WALL = 1
const TILE_DOOR = 2

var _rooms: Array[Rect2i] = []

# Keep track of RNG for determinism
var _rng = RandomNumberGenerator.new()

func generate(target: TileMapLayer) -> void:
	target.clear()
	_rooms.clear()

	_rng.seed = seed_val
	var noise = FastNoiseLite.new()
	noise.seed = seed_val
	noise.frequency = 0.05

	# 1. Base noise pass
	for y in range(height):
		for x in range(width):
			var val = noise.get_noise_2d(float(x), float(y))
			if val < wall_threshold:
				target.set_cell(Vector2i(x, y), TILE_FLOOR, Vector2i(0, 0))
			else:
				target.set_cell(Vector2i(x, y), TILE_WALL, Vector2i(1, 0))

	# 2. Carve rooms (at least 3 non-overlapping rects, inside 1..width-2)
	var attempts = 0
	while _rooms.size() < 3 and attempts < 100:
		attempts += 1
		var room_w = _rng.randi_range(5, 12)
		var room_h = _rng.randi_range(5, 12)
		var rx = _rng.randi_range(1, width - 2 - room_w)
		var ry = _rng.randi_range(1, height - 2 - room_h)
		var rect = Rect2i(rx, ry, room_w, room_h)

		var overlap = false
		for r in _rooms:
			if r.intersects(rect):
				overlap = true
				break
		if not overlap:
			_rooms.append(rect)
			for y in range(rect.position.y, rect.end.y):
				for x in range(rect.position.x, rect.end.x):
					target.set_cell(Vector2i(x, y), TILE_FLOOR, Vector2i(0, 0))

	# 3. Connect rooms with straight L-shaped corridors
	for i in range(_rooms.size() - 1):
		var r1 = _rooms[i]
		var r2 = _rooms[i+1]
		var p1 = r1.get_center()
		var p2 = r2.get_center()

		# L-shape: horizontal then vertical, or vertical then horizontal
		var corner
		if _rng.randf() < 0.5:
			corner = Vector2i(p2.x, p1.y)
		else:
			corner = Vector2i(p1.x, p2.y)

		_carve_line(target, p1, corner)
		_carve_line(target, corner, p2)

	# 4. Enforce edge walls
	for x in range(width):
		target.set_cell(Vector2i(x, 0), TILE_WALL, Vector2i(1, 0))
		target.set_cell(Vector2i(x, height - 1), TILE_WALL, Vector2i(1, 0))
	for y in range(height):
		target.set_cell(Vector2i(0, y), TILE_WALL, Vector2i(1, 0))
		target.set_cell(Vector2i(width - 1, y), TILE_WALL, Vector2i(1, 0))

func _carve_line(target: TileMapLayer, a: Vector2i, b: Vector2i) -> void:
	var x1 = min(a.x, b.x)
	var x2 = max(a.x, b.x)
	var y1 = min(a.y, b.y)
	var y2 = max(a.y, b.y)
	for x in range(x1, x2 + 1):
		_set_floor_if_not_edge(target, Vector2i(x, a.y))
	for y in range(y1, y2 + 1):
		_set_floor_if_not_edge(target, Vector2i(b.x, y))

func _set_floor_if_not_edge(target: TileMapLayer, pos: Vector2i) -> void:
	if pos.x > 0 and pos.x < width - 1 and pos.y > 0 and pos.y < height - 1:
		target.set_cell(pos, TILE_FLOOR, Vector2i(0, 0))

func count_floor_tiles(target: TileMapLayer) -> int:
	var count = 0
	for y in range(height):
		for x in range(width):
			if target.get_cell_source_id(Vector2i(x, y)) == TILE_FLOOR:
				count += 1
	return count

func find_rooms() -> Array[Rect2i]:
	return _rooms

